def norm(s): return re.sub(r'\W', '', s.lower())[:60]
exist = set()
for f in os.listdir(os.path.join(ROOT, 'data/sets')):
    if f.startswith(('v38-', 'v39-')): continue
    s = open(os.path.join(ROOT, 'data/sets', f), encoding='utf-8').read()
    d = json.loads(s[s.index('(') + 1:s.rindex(')')])
    for qq in d['questions']: exist.add(norm(qq['q']) + '|' + norm(' '.join(o['t'] for o in qq['opts'])))
files = []
for v, subj, items in ((38, 'algo', A1 + A2), (38, 'db', D1 + D2)):
    qs, dup = [], 0
    for it in items:
        k = norm(it['q']) + '|' + norm(' '.join(o['t'] for o in it['opts']))
        if k in exist: dup += 1; continue
        it = dict(it); it['multi'] = subj == 'db'; it['derived'] = True
        qs.append(it)
    key = 'v%d-%s' % (v, subj)
    st = {'key': key, 'variant': v, 'subject': subj, 'lang': 'kz', 'origLang': 'kz', 'source': 'tc',
          'title': 'Нұсқа %d · %s (М094 сынақ тестілері №1–2, сайтта жоқ сұрақтар)' % (v, 'Алгоритмдер' if subj == 'algo' else 'Деректер қоры'),
          'questions': [dict({'id': key + '-' + str(i + 1), 'n': i + 1}, **x) for i, x in enumerate(qs)]}
    open(os.path.join(ROOT, 'data/sets', key + '.js'), 'w', encoding='utf-8').write('Shyn.addSet(' + json.dumps(st, ensure_ascii=False) + ');\n')
    files.append(key); print(key, len(qs), 'dup skipped', dup)
idx = os.path.join(ROOT, 'data/index.js')
cur = json.loads(open(idx, encoding='utf-8').read().split('(', 1)[1].rsplit(')', 1)[0])
cur = [c for c in cur if not c.startswith(('v38-', 'v39-'))] + files
open(idx, 'w', encoding='utf-8').write('Shyn.setFiles(' + json.dumps(cur, ensure_ascii=False) + ');\n')
